<?php
namespace App\Http\Controllers; use App\Domain\CaseStudies\{CaseStudyIndexViewData,CaseStudyViewData}; use App\Models\{Client,Industry}; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; class PublicCaseStudyController extends Controller { public function index(Request $r,CaseStudyIndexViewData $d):View{return view('case-studies.index',['caseStudies'=>$d->get(max(1,$r->integer('page',1)),$r->integer('client')?:null,$r->integer('industry')?:null),'clients'=>Client::publiclyVisible()->orderBy('name')->limit(200)->get(['id','name']),'industries'=>Industry::publiclyVisible()->orderBy('title')->limit(200)->get(['id','title'])]+app(PublicSiteController::class)->sharedViewData($r));} public function show(Request $r,string $caseStudy,CaseStudyViewData $d):View{$x=$d->published($caseStudy);if(!$x){abort(404);}return view('case-studies.show',['caseStudy'=>$x,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($r));} }
